// Real credential validation tests via the API gateway
// Each test makes an authenticated API call that will fail if credentials are invalid
const gatewayUrl = 'https://mmurawala.app.n8n.cloud/webhook/api-gateway';
const apiKey = $env.N8N_GATEWAY_API_KEY || 'gw_k7Xm9pR2vT4wQ8nL3jF6hB1dY5sA0uC9eG2iK8oN4xZ';

// Lightweight read-only calls that validate credentials without side effects
const healthChecks = [
  {
    name: 'google_ads',
    category: 'marketing_ads',
    payload: { client: 'kahuna', api: 'google_ads', action: 'campaigns', params: { customer_id: 'test', limit: 1 } }
  },
  {
    name: 'hubspot',
    category: 'crm',
    payload: { client: 'kahuna', api: 'hubspot', action: 'contacts', params: { limit: 1 } }
  },
  {
    name: 'salesforce',
    category: 'crm',
    payload: { client: 'kahuna', api: 'salesforce', action: 'accounts', params: { limit: 1 } }
  },
  {
    name: 'ga4',
    category: 'analytics',
    payload: { client: 'kahuna', api: 'ga4', action: 'report', params: { date_range: 'last_7_days', metrics: ['sessions'], dimensions: ['date'] } }
  },
  {
    name: 'gmail',
    category: 'google_suite',
    payload: { client: 'kahuna', api: 'gmail', action: 'labels', params: {} }
  },
  {
    name: 'google_sheets',
    category: 'google_suite',
    payload: { client: 'kahuna', api: 'google_sheets', action: 'sheets', params: {} }
  },
  {
    name: 'google_calendar',
    category: 'google_suite',
    payload: { client: 'kahuna', api: 'google_calendar', action: 'calendars', params: {} }
  },
  {
    name: 'slack',
    category: 'communication',
    payload: { client: 'kahuna', api: 'slack', action: 'channels', params: { limit: 1 } }
  }
];

return healthChecks.map(check => ({
  json: {
    ...check,
    gateway_url: gatewayUrl,
    api_key: apiKey
  }
}));

const items = $input.all();
const results = [];
const now = new Date().toISOString();

for (const item of items) {
  const data = item.json;
  const isError = data.error || data.status === 'error' || data.statusCode >= 400;
  const isAuthError = data.error_type === 'auth_error' || data.statusCode === 401 || data.statusCode === 403;

  let status = 'healthy';
  let issue = null;

  if (isAuthError) {
    status = 'credential_expired';
    issue = 'OAuth token expired or API key invalid — re-authenticate in n8n credentials UI';
  } else if (isError) {
    status = 'unhealthy';
    issue = data.message || data.error || 'API returned an error';
  }

  results.push({
    api: data.name || 'unknown',
    category: data.category || 'unknown',
    status: status,
    issue: issue,
    checked_at: now
  });
}

const healthy = results.filter(r => r.status === 'healthy').length;
const credentialIssues = results.filter(r => r.status === 'credential_expired');
const unhealthy = results.filter(r => r.status === 'unhealthy');

return [{
  json: {
    overall_status: credentialIssues.length > 0 ? 'credential_issue' : unhealthy.length > 0 ? 'degraded' : 'healthy',
    health_report: results,
    checked_at: now,
    total_apis: results.length,
    healthy_count: healthy,
    credential_issues: credentialIssues.length,
    unhealthy_count: unhealthy.length,
    credential_issue_details: credentialIssues,
    needs_alert: credentialIssues.length > 0 || unhealthy.length > 0
  }
}];

const report = $input.first().json;
const issues = [...(report.credential_issue_details || []), ...(report.health_report || []).filter(r => r.status === 'unhealthy')];

const issueBlocks = issues.map(issue => ({
  type: 'section',
  text: {
    type: 'mrkdwn',
    text: `${issue.status === 'credential_expired' ? ':key:' : ':red_circle:'} *${issue.api}* (${issue.category})\n${issue.issue || 'Unknown issue'}`
  }
}));

const payload = {
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: 'n8n Health Check Alert' } },
    { type: 'section', text: { type: 'mrkdwn', text: `*Status:* ${report.overall_status} | *Healthy:* ${report.healthy_count}/${report.total_apis} | *Issues:* ${report.credential_issues + report.unhealthy_count}` } },
    { type: 'divider' },
    ...issueBlocks,
    { type: 'divider' },
    { type: 'context', elements: [{ type: 'mrkdwn', text: `Checked at: ${report.checked_at} | Source: Scheduled Health Check` }] }
  ]
};

return [{ json: payload }];
